  JobQueue.prototype.enqueue=async function(options={}){const id=options.id||crypto.randomUUID();if(!options.projectId)return originalEnqueue.call(this,{...options,id});const tenantId=await tenantForProject(options.projectId);if(!tenantId)throw Object.assign(new Error('project not found for entitlement admission'),{code:'TENANT_ISOLATION',statusCode:403});const capability=capabilityForJob(options.kind);const admission=await entitlements.reserve({tenantId,projectId:options.projectId,capability,amount:1,idempotencyKey:`job-ent:${options.idempotencyKey||id}`,resourceType:'job',resourceId:String(id),metadata:{kind:options.kind||'unknown'}});if(!admission.allowed)return this.get(admission.reservation.resource_id);try{return await originalEnqueue.call(this,{...options,id,metadata:{...(options.metadata||{}),entitlement:{planVersionId:admission.planVersionId,epoch:admission.epoch,capability}}})}catch(e){await entitlements.release({reservationId:admission.reservation.id,reason:'job-insert-failed'}).catch(()=>{});throw e}};
  async function finish(job,kind,extra={}){const r=(await pool.query("SELECT id FROM forge_entitlement_reservations WHERE resource_type='job' AND resource_id=$1 AND status='HELD' ORDER BY created_at DESC LIMIT 1",[job.id])).rows[0];if(r){if(kind==='release')await entitlements.release({reservationId:r.id,reason:extra.reason||'job-terminal'}).catch(()=>{});else await entitlements.settle({reservationId:r.id,actualAmount:1,metadata:extra}).catch(()=>{})}}
